# -*- coding: utf-8 -*-
"""工作流持久化：JSON 文件存储。"""
from __future__ import annotations
import json, time, uuid
from pathlib import Path
from ..constant import WORKING_DIR

_BASE = Path(WORKING_DIR).expanduser() / "workflows"

def _ensure():
    _BASE.mkdir(parents=True, exist_ok=True)

def _wf_path(wf_id: str) -> Path:
    return _BASE / f"{wf_id}.json"

def _run_path(run_id: str) -> Path:
    return _BASE / "runs" / f"{run_id}.json"

def list_workflows(profile: str | None = None) -> list[dict]:
    _ensure()
    out = []
    for p in sorted(_BASE.glob("*.json"), key=lambda x: x.stat().st_mtime, reverse=True):
        try:
            d = json.loads(p.read_text("utf-8"))
            out.append({"id": d["id"], "name": d.get("name", ""), "profile": d.get("profile", "default"),
                        "node_count": len(d.get("nodes", [])), "edge_count": len(d.get("edges", [])),
                        "created_at": d.get("created_at", 0), "updated_at": d.get("updated_at", 0)})
        except Exception:
            pass
    return out

def save_workflow(data: dict, create: bool = False) -> dict:
    _ensure()
    now = int(time.time() * 1000)
    if create or "id" not in data or not data["id"]:
        data["id"] = uuid.uuid4().hex[:12]
        data["created_at"] = now
    data["updated_at"] = now
    _wf_path(data["id"]).write_text(json.dumps(data, ensure_ascii=False, indent=1), "utf-8")
    return data

def get_workflow(wf_id: str) -> dict | None:
    p = _wf_path(wf_id)
    if not p.is_file():
        return None
    try:
        return json.loads(p.read_text("utf-8"))
    except Exception:
        return None

def delete_workflows(ids: list[str]) -> int:
    n = 0
    for i in ids:
        p = _wf_path(i)
        if p.is_file():
            p.unlink(); n += 1
    return n

def save_run(run: dict) -> None:
    _ensure()
    rp = _BASE / "runs"
    rp.mkdir(parents=True, exist_ok=True)
    (rp / f"{run['run_id']}.json").write_text(json.dumps(run, ensure_ascii=False), "utf-8")

def get_run(run_id: str) -> dict | None:
    p = _BASE / "runs" / f"{run_id}.json"
    if not p.is_file():
        return None
    try:
        return json.loads(p.read_text("utf-8"))
    except Exception:
        return None
